def sheet(cells: dict[str, str]) -> dict[str, int | str]:
    memo: dict[str, int | str] = {}
    active: set[str] = set()
    cache: dict[str, tuple] = {}

    def ast_of(name: str):
        hit = cache.get(name)
        if hit is not None:
            return hit
        raw = cells[name].strip()
        tree = _parse(raw[1:]) if raw.startswith("=") else ("n", int(raw))
        cache[name] = tree
        return tree

    def compute(name: str) -> int | str:
        if name in memo:
            return memo[name]
        stack: list[list] = [[("c", name), 0, None]]
        val = None
        while stack:
            fr = stack[-1]
            node = fr[0]
            kind = node[0]
            phase = fr[1]
            if kind == "n":
                val = node[1]
                stack.pop()
            elif kind == "c":
                nm = node[1]
                if phase == 0:
                    if nm not in cells:
                        val = 0
                        stack.pop()
                    elif nm in memo:
                        val = memo[nm]
                        stack.pop()
                    elif nm in active:
                        val = "#CYCLE!"
                        stack.pop()
                    else:
                        active.add(nm)
                        fr[1] = 1
                        stack.append([ast_of(nm), 0, None])
                else:
                    memo[nm] = val
                    active.remove(nm)
                    stack.pop()
            elif kind == "u":
                if phase == 0:
                    fr[1] = 1
                    stack.append([node[1], 0, None])
                else:
                    stack.pop()
                    if not isinstance(val, str):
                        val = -val
            elif kind == "b":
                if phase == 0:
                    fr[1] = 1
                    stack.append([node[2], 0, None])
                elif phase == 1:
                    if isinstance(val, str):
                        stack.pop()
                    else:
                        fr[1] = 2
                        fr[2] = val
                        stack.append([node[3], 0, None])
                else:
                    right = val
                    left = fr[2]
                    stack.pop()
                    val = _apply(node[1], left, right)
            elif kind == "i":
                if phase == 0:
                    fr[1] = 1
                    stack.append([node[2], 0, None])
                elif phase == 1:
                    if isinstance(val, str):
                        stack.pop()
                    else:
                        fr[1] = 2
                        fr[2] = val
                        stack.append([node[3], 0, None])
                elif phase == 2:
                    if isinstance(val, str):
                        stack.pop()
                    else:
                        cond = _rel(node[1], fr[2], val)
                        fr[1] = 3
                        stack.append([node[4] if cond else node[5], 0, None])
                else:
                    stack.pop()
            elif kind == "f":
                if fr[2] is None:
                    fr[2] = [[], None, 0]
                acc, err, idx = fr[2]
                args = node[2]
                if phase == 0:
                    if err is not None or idx >= len(args):
                        stack.pop()
                        if err is not None:
                            val = err
                        elif node[1] == "SUM":
                            val = sum(acc)
                        elif not acc:
                            val = 0
                        elif node[1] == "MIN":
                            val = min(acc)
                        else:
                            val = max(acc)
                    else:
                        arg = args[idx]
                        fr[2][2] = idx + 1
                        fr[1] = 1
                        if arg[0] == "E":
                            stack.append([arg[1], 0, None])
                        else:
                            stack.append([("r", arg[1]), 0, [0, []]])
                else:
                    fr[1] = 0
                    if isinstance(val, str):
                        fr[2][1] = val
                    elif isinstance(val, tuple):
                        acc.extend(val[1])
                    else:
                        acc.append(val)
            else:
                idx, acc = fr[2]
                names = node[1]
                if phase == 0:
                    if idx >= len(names):
                        val = ("vals", acc)
                        stack.pop()
                    else:
                        nm = names[idx]
                        fr[2][0] = idx + 1
                        if nm in cells:
                            fr[1] = 1
                            stack.append([("c", nm), 0, None])
                elif isinstance(val, str):
                    stack.pop()
                else:
                    acc.append(val)
                    fr[1] = 0
        return val

    return {nm: compute(nm) for nm in cells}


def _apply(op: str, left: int, right: int | str) -> int | str:
    if isinstance(right, str):
        return right
    if op == "+":
        return left + right
    if op == "-":
        return left - right
    if op == "*":
        return left * right
    if right == 0:
        return "#DIV/0!"
    q = abs(left) // abs(right)
    return -q if (left < 0) != (right < 0) else q


def _rel(op: str, a: int, b: int) -> bool:
    if op == "=":
        return a == b
    if op == "<>":
        return a != b
    if op == "<":
        return a < b
    if op == "<=":
        return a <= b
    if op == ">":
        return a > b
    return a >= b


def _parse(src: str):
    return _Parser(src).expr()


class _Parser:
    def __init__(self, s: str):
        self.s = s
        self.n = len(s)
        self.i = 0

    def skip(self) -> None:
        i = self.i
        s = self.s
        n = self.n
        while i < n and s[i] == " ":
            i += 1
        self.i = i

    def expr(self):
        left = self._mul()
        while True:
            self.skip()
            if self.i >= self.n or self.s[self.i] not in "+-":
                return left
            op = self.s[self.i]
            self.i += 1
            right = self._mul()
            left = ("b", op, left, right)

    def _mul(self):
        left = self._unary()
        while True:
            self.skip()
            if self.i >= self.n or self.s[self.i] not in "*/":
                return left
            op = self.s[self.i]
            self.i += 1
            right = self._unary()
            left = ("b", op, left, right)

    def _unary(self):
        self.skip()
        if self.i < self.n and self.s[self.i] == "-":
            self.i += 1
            return ("u", self._unary())
        return self._atom()

    def _atom(self):
        self.skip()
        s = self.s
        i = self.i
        c = s[i]
        if c == "(":
            self.i = i + 1
            node = self.expr()
            self.skip()
            self.i += 1
            return node
        if c.isdigit():
            return ("n", self._number())
        j = i + 1
        while j < self.n and s[j].isalpha():
            j += 1
        word = s[i:j]
        self.i = j
        if word in ("SUM", "MIN", "MAX", "IF"):
            self.skip()
            self.i += 1
            if word == "IF":
                return self._if()
            return self._agg(word)
        return ("c", word + str(self._number()))

    def _number(self) -> int:
        s = self.s
        i = self.i
        j = i
        n = self.n
        while j < n and s[j].isdigit():
            j += 1
        self.i = j
        return int(s[i:j])

    def _if(self):
        left = self.expr()
        op = self._cmp()
        right = self.expr()
        self.skip()
        self.i += 1
        then = self.expr()
        self.skip()
        self.i += 1
        els = self.expr()
        self.skip()
        self.i += 1
        return ("i", op, left, right, then, els)

    def _cmp(self) -> str:
        self.skip()
        i = self.i
        two = self.s[i:i + 2]
        if two in ("<>", "<=", ">="):
            self.i = i + 2
            return two
        self.i = i + 1
        return self.s[i]

    def _agg(self, name: str):
        args = []
        while True:
            if self._at_range():
                args.append(("R", self._range()))
            else:
                args.append(("E", self.expr()))
            self.skip()
            if self.s[self.i] == ",":
                self.i += 1
                continue
            self.i += 1
            break
        return ("f", name, args)

    def _at_range(self) -> bool:
        s = self.s
        n = self.n
        j = self.i
        while j < n and s[j] == " ":
            j += 1
        if j >= n or not ("A" <= s[j] <= "Z"):
            return False
        j += 1
        if j >= n or s[j] < "1" or s[j] > "9":
            return False
        j += 1
        if j < n and s[j].isdigit():
            j += 1
        while j < n and s[j] == " ":
            j += 1
        return j < n and s[j] == ":"

    def _range(self):
        c1, r1 = self._cell()
        self.skip()
        self.i += 1
        c2, r2 = self._cell()
        if c1 > c2:
            c1, c2 = c2, c1
        if r1 > r2:
            r1, r2 = r2, r1
        names = []
        for r in range(r1, r2 + 1):
            for c in range(ord(c1), ord(c2) + 1):
                names.append(chr(c) + str(r))
        return names

    def _cell(self):
        self.skip()
        col = self.s[self.i]
        self.i += 1
        return col, self._number()
